#!/usr/bin/env python3
"""Compute ground truth for CSX-145_Q2 from local CSX-145 inputs."""

from __future__ import annotations

import json
import re
from collections import Counter
from pathlib import Path


TASK_ID = "CSX-145_Q2"
EVENT_ID = "CSX-145"
EVENT_NAME = "Super Typhoon Yagi severe wind and rainfall impacts"
TASK_TYPE = "short_answer"
EVALUATION_MODE = "hybrid"
DIFFICULTY_LEVEL = "L2"
TARGET_FAMILY = "compound_wind_rain_impact_load_index"


def load_json(package_dir: Path, relative_path: str) -> dict:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def load_text(package_dir: Path, relative_path: str) -> str:
    return (package_dir / relative_path).read_text(encoding="utf-8", errors="ignore")


def first_number(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE | re.DOTALL)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1).replace(",", ""))


def score_wind(max_wind_kmh: float, max_wind_mph: float) -> int:
    if max_wind_kmh >= 200.0 or max_wind_mph >= 125.0:
        return 3
    if max_wind_kmh >= 150.0:
        return 2
    return 1


def score_rain(report_rain_mm: float) -> int:
    if report_rain_mm >= 250.0:
        return 3
    if report_rain_mm >= 100.0:
        return 2
    return 1


def score_impact(has_flood_or_landslide: bool, deaths: float, houses: float) -> int:
    if has_flood_or_landslide and deaths >= 100.0 and houses >= 10000.0:
        return 3
    if has_flood_or_landslide:
        return 2
    return 1


def score_service_exposure(population: float, amenity_count: int) -> int:
    population_threshold = population > 1_000_000
    amenity_threshold = amenity_count >= 75
    if population_threshold and amenity_threshold:
        return 3
    if population_threshold or amenity_threshold:
        return 2
    return 1


def load_class(total: int) -> str:
    if 10 <= total <= 12:
        return "extreme_compound_wind_rain_impact_load"
    if 7 <= total <= 9:
        return "elevated_mixed_hazard_impact_load"
    return "limited_compound_impact_signal"


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / "CSX-145"

    un_report_path = "data/event_reports/event_reports_001_Locked_anchor_report_NOAA_NESDIS.html"
    noaa_report_path = (
        "data/event_reports/event_reports_003_event_package.json_sour"
        "ce_plan.locked_event_anchor.evidence_url.html"
    )
    anchor_path = "data/event_reports/event_reports_004_Locked_event_anchor_Super_Typhoon_Yagi_severe_wind_and_rainfall_impacts.json"
    worldpop_path = "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json"
    osm_path = "data/exposure_impact/exposure_impact_001_Overpass_small_roads_and_critical_amenities.json"

    un_report = load_text(package_dir, un_report_path)
    noaa_report = load_text(package_dir, noaa_report_path)
    anchor = load_json(package_dir, anchor_path)
    worldpop = load_json(package_dir, worldpop_path)
    osm = load_json(package_dir, osm_path)

    un_wind_kmh = first_number(r"wind speeds reaching\s*([0-9,]+)\s*kilometres", un_report)
    un_wind_mph = first_number(r"\(([0-9,]+)\s*miles\)\s*per hour", un_report)
    noaa_rain_inches = first_number(r"dumping\s*([0-9.]+)\s*inches", noaa_report)
    noaa_rain_cm = first_number(r"\(([0-9.]+)\s*cm\)\s*of rain", noaa_report)
    noaa_wind_mph = first_number(r"wind speeds of around\s*([0-9.]+)\s*miles per hour", noaa_report)
    deaths = first_number(r"at least\s*([0-9,]+)\s*people are reported to have been killed", un_report)
    evacuated = first_number(r"evacuation of over\s*([0-9,]+)\s*people", un_report)
    houses = first_number(r"over\s*([0-9,]+)\s*houses damaged or destroyed", un_report)

    report_rain_mm = max(noaa_rain_inches * 25.4, noaa_rain_cm * 10.0)

    population = worldpop["population_sum"]["population"]
    amenity_counter: Counter[str] = Counter()
    for element in osm.get("elements", []):
        tags = element.get("tags") or {}
        amenity = tags.get("amenity")
        if amenity:
            amenity_counter[amenity] += 1

    counted_amenities = ["hospital", "police", "fire_station", "shelter", "school"]
    critical_amenity_count = sum(amenity_counter[name] for name in counted_amenities)
    has_flood_or_landslide = bool(re.search(r"flooding|landslides", un_report, flags=re.IGNORECASE))

    component_scores = {
        "wind_severity": score_wind(un_wind_kmh, max(un_wind_mph, noaa_wind_mph)),
        "rainfall_severity": score_rain(report_rain_mm),
        "impact_cascade": score_impact(has_flood_or_landslide, deaths, houses),
        "public_service_exposure_load": score_service_exposure(population, critical_amenity_count),
    }
    total_score = sum(component_scores.values())
    primary_score_ledger = {
        "wind": component_scores["wind_severity"],
        "rainfall": component_scores["rainfall_severity"],
        "impact": component_scores["impact_cascade"],
        "public_service": component_scores["public_service_exposure_load"],
    }
    event_window = anchor["temporal_window"]

    key_values = {
        "event_name": EVENT_NAME,
        "event_window": {
            "start_date": event_window["start_date"],
            "end_date": event_window["end_date"],
        },
        "index_name": "Compound Impact Load Index",
        "wind_metrics": {
            "un_landfall_wind_kmh": un_wind_kmh,
            "un_landfall_wind_mph": un_wind_mph,
            "noaa_sustained_wind_mph": noaa_wind_mph,
        },
        "rainfall_metrics": {
            "noaa_report_rain_inches": noaa_rain_inches,
            "noaa_report_rain_cm": noaa_rain_cm,
            "report_rain_mm_used": round(report_rain_mm, 1),
        },
        "impact_metrics": {
            "flood_or_landslide_terms_present": has_flood_or_landslide,
            "deaths_at_least": deaths,
            "evacuated_people_over": evacuated,
            "houses_damaged_or_destroyed_over": houses,
        },
        "public_service_exposure_metrics": {
            "worldpop_population_sum": round(population, 2),
            "critical_public_service_amenity_count": critical_amenity_count,
            "amenity_counts": {name: amenity_counter[name] for name in counted_amenities},
        },
        "component_scores": component_scores,
        "total_index_score": total_score,
        "load_class": load_class(total_score),
        "class_thresholds": {
            "extreme_compound_wind_rain_impact_load": "10-12",
            "elevated_mixed_hazard_impact_load": "7-9",
            "limited_compound_impact_signal": "4-6",
        },
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": TASK_TYPE,
        "target_family": TARGET_FAMILY,
        "evaluation_mode": EVALUATION_MODE,
        "difficulty_level": DIFFICULTY_LEVEL,
        "primary_gt": {
            "answer": load_class(total_score),
            "answer_type": "score_ledger",
            "total_index_score": total_score,
            "score_ledger": primary_score_ledger,
            "canonical_stance": (
                "Yagi reaches the extreme compound wind-rain impact load class because all four tests score 3."
            ),
            "required_claims": [
                "Wind scores 3: 213 km/h and 133 mph.",
                "Rain scores 3: 254.0 mm report rain.",
                "Impact scores 3: flood or landslide terms, 179 deaths, and 47,500 houses.",
                "Public-service scores 3: 2,485,012.26 people and 89 amenities.",
            ],
            "required_metrics": {
                "wind_kmh": un_wind_kmh,
                "wind_mph": max(un_wind_mph, noaa_wind_mph),
                "rain_mm": round(report_rain_mm, 1),
                "deaths": deaths,
                "houses": houses,
                "population": round(population, 2),
                "amenities": critical_amenity_count,
            },
            "forbidden_claims": [
                "Do not use the elevated or limited class.",
                "Do not claim outage, flood depth, building-level damage, or full landslide inventory.",
            ],
        },
        "key_values": key_values,
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Final score and load class",
                    "points": 4,
                    "description": "Gives total score 12/12 and the class extreme compound wind-rain impact load.",
                    "partial_credit": "Award 2-3 points for the correct top-band class with a missing or slightly misstated score; award 1 point for a correct high-load direction without the exact class.",
                },
                {
                    "name": "Component-score ledger",
                    "points": 4,
                    "description": "Reports wind severity 3, rainfall severity 3, impact cascade 3, and public-service exposure load 3.",
                    "partial_credit": "Award 1 point for each correct component score, or up to 3 points for a correct total with one component mislabeled.",
                },
                {
                    "name": "Wind and rainfall anchors",
                    "points": 3,
                    "description": "Uses the relevant wind and rainfall anchors, including 213 km/h or 125+ mph winds and reported rainfall at or above 250 mm.",
                    "partial_credit": "Award 1-2 points for correct threshold logic with incomplete or approximate values.",
                },
                {
                    "name": "Impact and exposure anchors",
                    "points": 3,
                    "description": "Connects flooding or landslides with at least 179 deaths, over 47,500 damaged or destroyed houses, population above 1,000,000, and 89 critical/public-service amenities.",
                    "partial_credit": "Award 1-2 points for including only impact anchors or only exposure anchors, or for using correct thresholds without exact values.",
                },
                {
                    "name": "Index arithmetic and class mapping",
                    "points": 3,
                    "description": "Shows that 3 + 3 + 3 + 3 = 12 and maps 12 to the 10-12 top band.",
                    "partial_credit": "Award 1-2 points for correct arithmetic without the class mapping, or correct class mapping with one arithmetic slip.",
                },
                {
                    "name": "Concise computed interpretation",
                    "points": 2,
                    "description": "Ties the top-band result to combined wind, rain, reported-loss, population, and public-service indicators without a broad disaster narrative.",
                    "partial_credit": "Award 1 point for a generic interpretation that is only partly tied to the computed values.",
                },
                {
                    "name": "Scope and answer discipline",
                    "points": 1,
                    "description": "Keeps the answer concise, follows the requested format, and avoids extra-data claims beyond the index values.",
                    "partial_credit": "Award 0.5 points if the answer is mostly concise but includes minor extra-data or off-format material.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "notes": "All values are extracted from local CSX-145 inputs. No network access is used.",
            "source_files": [
                    un_report_path,
                    noaa_report_path,
                    anchor_path,
                    worldpop_path,
                    osm_path,
                ],
                "notes": [
                    "Off-event gridded precipitation summaries are not required for the official rain score.",
                    "WorldPop and OpenStreetMap values are evaluated as package-relative exposure and public-service derived statistics, not as confirmed affected-population or outage counts.",
                ],
            },
    }

    output_path = task_dir / "computed_gt.json"
    with output_path.open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
